INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch02$PT127-S1-Q12$batch02$, 127, 1, 12, $batch02$Flaw$batch02$, $batch02$Many people say that the press should not pry into the personal lives of private individuals. But the press has the right to publish any story of interest to the public unless that story is libelous. So, if a story about a private individual is not libelous, the press has an obligation to publish it, for such information is clearly of interest to the public.$batch02$, $batch02$The argument’s reasoning is vulnerable to criticism on the grounds that the argument presumes, without giving warrant, that$batch02$, $batch02$B$batch02$, true, $batch02$Batch 02 approved 2026-10-01; question text from local bank.$batch02$ FROM lr_sections s WHERE s.preptest=127 AND s.section=1 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch02$PT127-S1-Q12$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$A$batch02$, $batch02$the press can publish nonlibelous stories about private individuals without prying into their personal lives$batch02$, $batch02$Not Assumed$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT127-S1-Q12$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$A$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$B$batch02$, $batch02$one’s having a right to do something entails one’s having an obligation to do it$batch02$, $batch02$Correct$batch02$, true FROM lr_questions q WHERE q.qid=$batch02$PT127-S1-Q12$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$B$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$C$batch02$, $batch02$the publishing of information about the personal lives of private individuals cannot be libelous$batch02$, $batch02$Not Assumed$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT127-S1-Q12$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$C$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$D$batch02$, $batch02$if one has an obligation to do something then one has a right to do it$batch02$, $batch02$Backwards$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT127-S1-Q12$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$D$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$E$batch02$, $batch02$the press’s right to publish always outweighs the individual’s right not to be libeled$batch02$, $batch02$Out of Scope$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT127-S1-Q12$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$E$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch02$PT127-S1-Q12$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch02$Conclusion$batch02$, $batch02$If a story about a private individual is not libelous, the press has an *obligation* to publish it.$batch02$), (1, $batch02$Evidence$batch02$, $batch02$The press has the *right* to publish any story of public interest unless it is libelous, and stories about private individuals are of public interest.$batch02$), (2, $batch02$Evaluate$batch02$, $batch02$The premises deliver a right. The conclusion announces an obligation. Those are different. You have the right to paint your house purple; you have no duty to. Watch for a word in the conclusion that never appears in the evidence. "Obligation" is that word here.$batch02$), (3, $batch02$Goal$batch02$, $batch02$Look for the assumption that a right brings an obligation with it.$batch02$)) v(position,label,body) WHERE q.qid=$batch02$PT127-S1-Q12$batch02$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch02$A$batch02$, $batch02$Whether publishing requires prying does not matter to the argument. Negate it (publishing such stories does involve prying) and the author still reaches the same conclusion, since he has brushed the prying objection aside.$batch02$), ($batch02$B$batch02$, $batch02$This bridges the gap exactly. The evidence establishes a right to publish; the conclusion claims an obligation to publish. Negate (B) (having a right does not entail an obligation) and the conclusion no longer follows.$batch02$), ($batch02$C$batch02$, $batch02$The conclusion is conditional: *if* a story is not libelous. The author allows that some stories about private lives might be libelous.$batch02$), ($batch02$D$batch02$, $batch02$This runs the link the wrong way: obligation → right. The argument needs right → obligation.$batch02$), ($batch02$E$batch02$, $batch02$Libelous stories are set aside by the conclusion's "if not libelous" condition. No weighing of the two rights is involved.$batch02$)) v(letter,body) WHERE q.qid=$batch02$PT127-S1-Q12$batch02$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
